-- ─────────────────────────────────────────────────────────────
-- SALON: WHO KEEPS US SAFE? · add the fire extinguisher block
-- For the copy already in the database (lesson b2ba19c7-4dc1-45c5-836e-bacb83c3d78c).
-- Moves "Day One: who keeps you safe?" to the end and puts five fire
-- extinguisher steps (15 minutes) in front of it. 60 → 75 minutes.
-- Run once. It refuses to run twice: it only acts if the lesson still has 24 steps.
-- ─────────────────────────────────────────────────────────────

do $$
begin
  if (select count(*) from slots where lesson_id = 'b2ba19c7-4dc1-45c5-836e-bacb83c3d78c' and session_id is null) <> 24 then
    raise exception 'Expected 24 steps in the lesson. It has been changed already, so nothing was done.';
  end if;

  update slots set order_index = 28
  where lesson_id = 'b2ba19c7-4dc1-45c5-836e-bacb83c3d78c' and session_id is null and order_index = 23;

  insert into slots (
    lesson_id, session_id, order_index, name, lead_phase,
    duration_mins, end_behaviour, pause_before_advance, screen_delay_secs,
    host_content, screen1_content, screen2_content
  )
  select
    'b2ba19c7-4dc1-45c5-836e-bacb83c3d78c', null, v.order_index, v.name, v.lead_phase,
    v.duration_mins, v.end_behaviour, false, 0,
    v.host::jsonb, coalesce(v.touch, v.host)::jsonb, coalesce(v.touch, v.host)::jsonb
  from (values
  -- 24 · Fire at station 3 (2 min)
  (23, 'Fire at station 3', 'Demonstrate', 2, 'screen1_continue',
    '{"type":"text_slide","title":"Fire at station 3!","text":"A hairdryer has caught fire.\nThere is a water extinguisher\nright next to you.\n\nDo you use it? Why?","size":"lg"}',
    null),

  -- 25 · Know your extinguisher (3 min)
  (24, 'Know your extinguisher', 'Demonstrate', 3, 'screen1_continue',
    '{"type":"image","url":"https://sxrhecwyhqwdwwfawojn.supabase.co/storage/v1/object/public/lesson-media/lessons/salon-who-keeps-us-safe/slide-15.jpg","file_name":"slide-15.jpg"}',
    null),

  -- 26 · Fire extinguisher grid (5 min)
  (25, 'Fire extinguisher grid', 'Demonstrate', 5, 'screen1_continue',
    '{"type":"host_timer","label":"Fill in your extinguisher grid","duration_secs":240}',
    '{"type":"text_slide","title":"On your table","text":"Draw 3 columns:\nTYPE  |  BEST FOR  |  WRONG FIRE?\n\nWater, CO2, Foam,\nDry powder, Fire blanket","size":"md"}'),

  -- 27 · Let's check: the wrong extinguisher (2 min)
  (26, 'Let''s check: the wrong extinguisher', 'Demonstrate', 2, 'screen1_continue',
    '{"type":"image","url":"https://sxrhecwyhqwdwwfawojn.supabase.co/storage/v1/object/public/lesson-media/lessons/salon-who-keeps-us-safe/slide-16.jpg","file_name":"slide-16.jpg"}',
    null),

  -- 28 · Which one would you grab? (3 min)
  (27, 'Which one would you grab?', 'Demonstrate', 3, 'screen1_continue',
    '{"type":"wheel_spinner","prompt":"Which extinguisher? Write the colour band on your table.","items":["Hairdryer on fire","Towels in the bin","A client''s gown on fire","Chip pan in the staff room","Paper by the till","Straighteners sparking","Hairspray alight","Toaster in the staff room"]}',
    null)
  ) as v(order_index, name, lead_phase, duration_mins, end_behaviour, host, touch);

  update lessons
  set estimated_duration_mins = 75,
      ai_notes = '{"rationale":"Session 2 of Hayley''s health and safety unit (VTCT UV10477, Follow health and safety in the salon). Session 1 covered hazards, hazard and risk, five laws as a carousel, COSHH, the Saturday Shift game and a mini risk assessment. This session fills the gaps in learning outcome 1: the employer''s responsibilities (1f, on the external paper), the laws not yet met (Workplace Regulations, Manual Handling, PUWER, Environmental Protection Act), and safe and hygienic working (1c and 1g). One question runs through the hour: on your first day, who keeps the salon safe, the employer or me? A BBC report on a dirty barbershop opens it, and learners keep an EMPLOYER and ME list on their table all lesson. Hayley''s own slides (HS Acts, Hazards and hygiene, the fill-the-gaps sheet) are rebuilt in Canva in her order. The product is a Day One induction board for a new junior, judged by another table as an inspector would. A 15 minute block on fire extinguishers (outcome 2a, from Hayley''s fire extinguisher slides and fire-fighting handout) closes the session; the rest of outcome 2 is saved for Session 3. Nothing is printed.","objectives":["State what an employer must do to keep staff and clients safe, and name the law behind it.","Explain how good hygiene stops infection passing from one client to the next.","Judge whether a salon is meeting the law, and give a reason."],"run_sheet":[{"slot_index":0,"teacher_says":"It''s your first day at a salon. Whose job is it to keep you safe: your boss, you, or both? Draw a line down the middle of your table. Write EMPLOYER on one side and ME on the other. That line stays all lesson.","watch_for":"Learners: standing at the tables, each with a pen. Take a quick show of hands: boss, me, both. Do not give the answer; it comes back in the last step. Last week was spotting hazards and the five laws. This week is whose job each thing is, and hygiene. Technique: open a question now and close it at the end."},{"slot_index":1,"teacher_says":"Say this BEFORE the clip: this is a real BBC London report. Watch for three things: what happened to Jacob, what they found in the shop, and whose job it was to stop it. Write anything you spot on your table.","watch_for":"Learners: at the tables, writing as they watch. BBC London, 2 minutes 50 seconds, plays to the end then moves on. What is in it: Jacob got a fungal scalp infection from dirty tools and needed about four weeks of antibiotics. He describes pus and blood on his pillow, so warn the group first. Inside an East London shop the BBC found bloodstained, rusty razors. A dermatologist names folliculitis, herpes and warts. UK barbers need no licence, and London''s councils could not say how many barber shops they had. Technique: a watching task set before the clip."},{"slot_index":2,"teacher_says":"Talk at your table: whose fault was Jacob''s infection? Then write a verdict on your table: shut it down, or let it stay open? One reason.","watch_for":"Learners: at the tables. Take one verdict per table. Listen for ''the barber didn''t clean the clippers'' (the employee''s duty) and ''the owner should have trained them and checked'' (the employer''s duty). Both are right, which is the lesson. Keep their verdicts on the table: they judge again with the law at step 19. Technique: judge before being taught, then judge again."},{"slot_index":3,"teacher_says":"Say this BEFORE the clip: a barrister explains the law in about a minute and a half. Write on the EMPLOYER side of your table everything he says the employer must do.","watch_for":"Learners: at the tables, writing on the EMPLOYER side. Christian Weaver, ''The Law in 60 Seconds'', 1 minute 33 seconds. He covers: the Health and Safety at Work Act 1974; a safe system of work and a safe place of work; risk assessments; consulting staff; clear information on safety. Breaking the law can be a crime, and the Employment Rights Act 1996 means you cannot be sacked for raising a safety concern. Afterwards, ask each table for one thing they wrote. Technique: a watching task with a written output."},{"slot_index":4,"teacher_says":"Hayley''s laws. Each box says what the employer must do. Your job: on the ME side, write what YOU must do for each one. Four laws, four minutes.","watch_for":"Learners: at the tables. TABLE TASK 1. Hayley''s ''HS Acts'' slides: Health and Safety at Work Act, Workplace (Health, Safety and Welfare) Regulations, Manual Handling and PUWER (work equipment). The last three were not covered last week. Good answers: report problems; keep the salon clean; lift from the knees; only use equipment you are trained on. Stretch: give a salon example for each. Technique: predict, then check against the model."},{"slot_index":5,"teacher_says":"Let''s check. Tick each one you had on your table. Add anything you missed.","watch_for":"Learners: at the tables, ticking and adding. Ask which table got all four. Point to the PUWER line: following manufacturers'' instructions is the employee''s half of that law. Technique: self-check against a model answer."},{"slot_index":6,"teacher_says":"You met these four last week: PPE, COSHH, electricity and RIDDOR. Last week was what they mean in a salon. This time: what is YOUR duty? Three minutes.","watch_for":"Learners: at the tables, ME side. This should be faster than the first four, because they know the laws. If a table writes what the law means instead of their duty, ask ''and what do YOU have to do?''. Technique: retrieval, then a new angle on what they already know."},{"slot_index":7,"teacher_says":"Tick and add. Which one did nobody think of?","watch_for":"Learners: at the tables. Often missed: reporting when PPE supplies run low, and disposing of products correctly as part of COSHH. Technique: self-check."},{"slot_index":8,"teacher_says":"Before you show the slide: your boss has to pay for three kinds of insurance. Guess what each one is for. Then show the slide. Which one pays if a client trips? If you get hurt? If a colour goes wrong?","watch_for":"Learners: at the tables, adding to the EMPLOYER side. This is specification criterion 1f, which is on the external paper and was not in Hayley''s slides: employer''s liability, public liability and professional indemnity insurance; displaying the health and safety rules and fire plan; training; records; monitoring; asking experts. Point out that employer''s liability insurance is a legal must for any salon with staff. Technique: predict before reveal."},{"slot_index":9,"teacher_says":"Race. Write the numbers 1 to 12 down your table and the missing word next to each. Every word in the box is used once. Three minutes. Go.","watch_for":"Learners: at the tables. TABLE TASK 2. From Hayley''s fill-the-gaps sheet, rewritten a little for the screen. COSHH is dated 2002 here (the sheet said 2003). Answers: 1 hazard, 2 risk, 3 manufacturers'', 4 safety, 5 neutralisers, 6 hairdryer, 7 COSHH, 8 protective, 9 clients, 10 clothes, 11 bath, 12 deodorant. First table with all twelve wins. Technique: a timed retrieval race."},{"slot_index":10,"teacher_says":"Back to Jacob. Draw it on your table: how did the germs get from the last client to Jacob? Then draw a big X where YOU could have stopped it.","watch_for":"Learners: at the tables, drawing. A good drawing: client A, then clippers, comb, towel or the stylist''s hands, then client B. Good X''s: sterilise the tools, a fresh towel, washing or sanitising hands, a clean gown. That is the whole of ''why hygiene stops infection''. Germs need a route, and hygiene breaks it. Technique: do it before being told."},{"slot_index":11,"teacher_says":"Hayley''s four habits. Thumbs up for each one you did in the salon this week.","watch_for":"Learners: at the tables. A quick thumbs check, so keep it moving. Link each habit to the chain they just drew. Technique: a quick personal check."},{"slot_index":12,"teacher_says":"Four ways to sterilise. Which one would have saved Jacob? Clean, disinfect and sterilise are not the same thing: cleaning removes the dirt you can see, disinfecting kills most germs, sterilising kills all of them.","watch_for":"Learners: at the tables. Tools must be cleaned of hair and product first, or the solution cannot reach the surface. An autoclave sterilises with steam under pressure (metal tools). Barbicide-type solution is for combs and brushes, fully covered and changed daily. A UV cabinet keeps clean tools clean. Ask which ones this salon uses. Technique: link the new idea to the case study."},{"slot_index":13,"teacher_says":"Before the slide: which bin does each of these go in? Point at the bin you think. Then press next to see Hayley''s slide.","watch_for":"Learners: at the tables. Answers: razor blade, sharps box; tint tube, hazardous waste; hair clippings, general waste; cardboard, recycling. The next step is Hayley''s slide with all four kinds, so keep this one short. Technique: predict before reveal."},{"slot_index":14,"teacher_says":"Were you right? Salons can be fined for getting this wrong. That''s the Environmental Protection Act.","watch_for":"Learners: at the tables. The Environmental Protection Act is on the specification''s list of laws and was not covered last week. Technique: check the prediction."},{"slot_index":15,"teacher_says":"Look at the person next to you: shoes, jewellery, hair. Would they pass? Kindly.","watch_for":"Learners: at the tables. Keep it light and kind. Nobody comments on bodies, only on things you can change: shoes, jewellery, a tied-back sleeve. Technique: apply it to yourself."},{"slot_index":16,"teacher_says":"Who has to pay for all this kit? The employer, under the PPE regulations. Now, all of you to the touch screens.","watch_for":"Learners: at the tables, then MOVE. Say clearly: half the class to each touch screen. Technique: close the teaching part with the employer link."},{"slot_index":17,"teacher_says":"Read each question aloud. Talk to the people at your screen, then one person taps. Take turns tapping.","watch_for":"Learners: at the touch screens, half the class at each. The question shapes are mixed on purpose: best answer (1, 6, 7), true or false (2, 5, 8) and odd one out (3). In 6 and 7 two options sound reasonable, so ask why. Q2: false, employers cannot charge for safety equipment. Technique: mixed question shapes, talk before tapping."},{"slot_index":18,"teacher_says":"Back to the barbershop from the start. Now you know the law. Vote. Then go back to your tables.","watch_for":"Learners: at the touch screens, then MOVE back to the tables. Compare with the verdicts they wrote at step 3. Ask one person to name the laws broken: COSHH (how the products are used), PUWER (equipment in good order), and the Health and Safety at Work Act (a safe system of work). Technique: judge again with new knowledge."},{"slot_index":19,"teacher_says":"Your salon is taking on a new junior on Monday. Wipe your table and make their Day One board in three parts: what the salon promises, what I promise, and my hygiene routine.","watch_for":"Learners: back at the tables. Sketch the three columns on the board as the model, because the big screen shows a timer next. Success criteria: at least three employer promises, each with its law named; at least three ''I promise'' duties; a hygiene routine for before, during and after a client. Technique: create a product against criteria."},{"slot_index":20,"teacher_says":"Seven minutes. Every person writes something. Use your EMPLOYER and ME lists from earlier.","watch_for":"Learners: at the tables, writing. TABLE TASK 3. The brief stays on the touch screens while the timer runs. Push for a law next to every promise. Stretch: add the insurance, and one thing from the BBC report the new junior must never do. The timer moves on by itself. Technique: create, then test each other''s work."},{"slot_index":21,"teacher_says":"Move one table round. You are the inspector. Read their board. Pass, needs work, or shut down? Write your verdict, one reason and one law on their table.","watch_for":"Learners: MOVE one table clockwise. The verdict guide is on the touch screens. A strong verdict names what is missing (''no law next to the towels promise'') and a law. Watch that verdicts are fair and kind. Technique: peer assessment against criteria."},{"slot_index":22,"teacher_says":"Each table: read out the verdict you gave, and your reason. Owners: do you agree?","watch_for":"Learners: at the board they judged. Take every table if there is time. Correct any law that is wrong. If a board got SHUT DOWN, ask what one change would save it. Technique: justify a judgement aloud."},{"slot_index":23,"teacher_says":"One last thing before you go. A hairdryer at station 3 catches fire. The extinguisher next to you is water. Do you use it? Write YES or NO on your table, and one reason.","watch_for":"Learners: at the tables. Count the yeses and noes. Do not give the answer yet. The right answer is NO: water conducts electricity, so you risk an electric shock. Unplug it only if it is safe, then use CO2, and raise the alarm. This opens specification outcome 2 (locate and use firefighting equipment), which session 3 covers in full with the building tour. Technique: predict before reveal."},{"slot_index":24,"teacher_says":"Every extinguisher in the UK is red. The coloured band tells you what is inside. So, the hairdryer: which one? (CO2, the black band.) Water was the wrong choice. Why?","watch_for":"Learners: at the tables. This is Hayley''s fire extinguisher PowerPoint on one slide, in her order: water, dry powder, foam, CO2, wet chemical, fire blanket. Note: Hayley''s fire-fighting handout labels foam yellow; foam is cream, and yellow is wet chemical. Say this if anyone has the handout. A salon usually has CO2 for the electrics and water or foam for paper and towels. Ask: which ones are in our salon? Technique: answer the prediction, then teach."},{"slot_index":25,"teacher_says":"Wipe a space. Draw three columns: Type, Best for, and What happens if you use it on the wrong fire. Five rows: water, CO2, foam, dry powder, fire blanket. The slide has gone, so this is from memory. Four minutes.","watch_for":"Learners: at the tables. TABLE TASK 4. This is Hayley''s fire-fighting handout, done on the table with no printing. Draw the three headings on the board before the timer starts, because the big screen shows a timer. The third column is the hard one: water on electrics gives a shock, water on burning oil gives a fireball, CO2 horn freezes, powder in a small room means you cannot breathe or see. Stretch: add the colour band to each row, and the wet chemical extinguisher. The timer moves on by itself. Technique: retrieval from memory, then check."},{"slot_index":26,"teacher_says":"Check your grid. Tick what you got. Add what you missed in a different colour.","watch_for":"Learners: at the tables, checking their own grid. Ask which row most tables missed. Usually the third column for CO2 and powder. Technique: self-check against a model."},{"slot_index":27,"teacher_says":"I spin, you race. Write the colour band of the extinguisher you would grab, then hold up your hands. First correct table scores. Then the question from Hayley''s last slide: which extinguishers should a hair salon have?","watch_for":"Learners: at the tables. Answers: hairdryer, straighteners and toaster: CO2 (black), after unplugging if safe. Towels, paper: water (red) or foam (cream). Gown or clothing: fire blanket. Chip pan: fire blanket or wet chemical (yellow), never water. Hairspray alight: foam (cream), CO2 or powder. Spin four or five times. Close with Hayley''s question: a salon needs CO2 for the electrics and water or foam for paper and towels, plus a fire blanket if there is a kitchen. Technique: a timed retrieval race."},{"slot_index":28,"teacher_says":"So, on day one, whose job is it: your boss or you? (Both.) The employer gives you a safe salon, the kit and the training. You use it, follow it and report it.","watch_for":"Learners: at the tables. This closes the question from step 1. Next session: the rest of fire and emergencies (specification outcome 2): alarms, evacuation, first aid and the accident book. Technique: close the loop."}],"verify_before_teaching":["Watch the BBC London clip (step 2, 2 minutes 50 seconds) to the end. Jacob describes pus and blood on his pillow, and there are photos of bloodstained razors. Warn the group before it plays.","Watch the Christian Weaver clip (step 4, 1 minute 33 seconds). It is general UK workplace law, not salon-specific, which is why the next step is Hayley''s salon slides.","The slides were rebuilt from Hayley''s PowerPoints in Canva. Check the wording reads as hers. Spelling was tidied (''Lets'''' to ''Let''''s'') and COSHH is dated 2002 on the gap-fill (her sheet said 2003).","Nothing is printed. Learners write on the whiteboard tables at steps 1 to 17 and 20 to 29. Every learner needs a pen, and tables are wiped before step 20.","The whole class moves twice: to the touch screens after step 17, and back to the tables after step 19. At step 22 every table moves round one.","Steps 21 and 22 use a timer on the big screen that moves on by itself. If a table needs longer, pause before it runs out.","Fire extinguishers are now steps 24 to 28. Hayley''s fire-fighting handout labels foam yellow; it is cream (yellow is wet chemical). Alarms, evacuation, first aid and the accident book are left for Session 3, with the department tour."],"safety_note":"The BBC clip includes a first-hand description of a scalp infection and photos of dirty razors. Warn learners first.","media_requests":[],"brief":{"topic":"Employer responsibilities, safety and hygiene in the salon","level":"Level 1","department":"Professional and Creative","three_screens":true}}'::jsonb
  where id = 'b2ba19c7-4dc1-45c5-836e-bacb83c3d78c';
end $$;
